"""Independent raw-cohort audit: no benchmark/analyzer imports and no JVM launch.

Scope: the qualified fully consumed, normally selected ordered-factorized study.
All 54 scheduled processes and all five measurements per process are retained.
An optional primary results JSON is compared only after raw estimates are computed.
Use --self-check for Java-free arithmetic, fixture, and schedule checks.
"""
import argparse
from collections import Counter
import hashlib
import itertools
import json
import math
from pathlib import Path
import re
import struct

ARMS = ('ordinary', 'initial', 'always')
PAIRS = (('always', 'initial'), ('initial', 'ordinary'), ('always', 'ordinary'))
ORDERS = ((0, 1, 2), (0, 2, 1), (1, 0, 2), (1, 2, 0), (2, 1, 0), (2, 0, 1))
RAW = ('launch.json', 'process.json', 'inputs-before.json', 'inputs-after.json',
       'console.log', 'samples.jsonl', 'gc.log', 'validation.json')
METRICS = ('totalNs', 'allThreadAllocatedBytes', 'callerThreadAllocatedBytes', 'connectionNs',
           'prepareNs', 'evaluateNs', 'firstRowAfterEvaluateNs', 'prefixConsumeNs', 'tailConsumeNs',
           'consumeNs', 'closeNs', 'retainedReadNs', 'ledgerPeakBytes', 'projectedOpportunities',
           'projectedBindingSetsCreated', 'projectedMaterializedValues', 'sourceLazyCallsAtPrefixBoundary',
           'projectedMaterializedValuesAtPrefixBoundary')
EVENTS = ('probes', 'hits', 'collisions', 'invalidations', 'unsupportedValues', 'clearCalls', 'resizes',
          'rehashDiscards', 'lowHitDisable', 'initialAdmissionRefusals', 'growthAdmissionRefusals',
          'collectedMisses', 'weakEntryAllocations', 'ownerReferenceAllocations')
FIXED_FLAGS = ['-Xms1024m', '-Xmx1024m', '-XX:+UseG1GC', '-XX:ObjectAlignmentInBytes=8',
               '-XX:+UseCompressedOops', '-XX:+UseCompressedClassPointers',
               '-Drdf4j.lmdb.hotCounters=true', '-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=536870912']
ROUTE = [{'point': 'ORDER', 'label': 'ORDER BY dispatch', 'strategy': 'orderedFactorizedSort',
          'mode': 'normal', 'count': 1}]
IR_ZERO = ('irPlanned', 'irOpened', 'irRows', 'compiledBinds', 'interpretedBinds',
           'aggregateCompiledBinds', 'aggregateInterpretedBinds', 'hostedGeneric',
           'unhostedHardDeclines', 'leftJoinReplayMaterializations')
M32, M64 = (1 << 32) - 1, (1 << 64) - 1


def need(condition, message):
    if not condition:
        raise ValueError(message)


def read(path):
    return json.loads(Path(path).read_text())


def sha(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def object_sha(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, allow_nan=False).encode()).hexdigest()


def integer(value):
    return type(value) is int and value >= 0


def median(values):
    values = sorted(values)
    n = len(values)
    need(n > 0, 'No observations')
    return values[n // 2] if n % 2 else (values[n // 2 - 1] + values[n // 2]) / 2


def reduce_values(values, mean=False):
    values = list(values)
    if all(v is None for v in values):
        return None
    need(all(v is not None for v in values), 'Metric availability changed within a process')
    return sum(values) / len(values) if mean else median(values)


def ratios(values):
    defined = [v for v in values if v is not None]
    return {'pairedRatios': values, 'definedPairs': len(defined),
            'medianRatio': median(defined) if defined else None,
            'range': [min(defined), max(defined)] if defined else None,
            'allSixBelowOne': len(defined) == 6 and all(v < 1 for v in defined)}


def fixture_oracle(args):
    """Generate ASCII lexical hashes directly, independently of the optimized oracle."""
    width, prefix, tail = (args[k] for k in ('width', 'prefix-probes', 'tail-probes'))
    total = prefix + tail
    need(args['consumption'] == 'full' and total % width == 0, 'Audit scope requires full rows')
    lengths, hashes = {}, {}
    recipe = hashlib.sha256(b'phase-memo-insertion-recipe-v1\n')
    checksum = characters = 0
    for row in range(total // width):
        row_hash = 0xCBF29CE484222325
        for column in range(width):
            j = row * width + column
            if args['pattern'] == 'cold-hot':
                key = j if j < prefix else (j - prefix) % args['working-set']
            elif args['pattern'] == 'hot-unique':
                key = j % args['working-set'] if j < prefix else args['working-set'] + j - prefix
            else:
                need(args['pattern'] == 'warm-cycle', 'Unknown phase pattern')
                key = j % args['bootstrap-keys'] if j < prefix else (
                    args['bootstrap-keys'] + (j - prefix) % args['working-set'])
            if key not in hashes:
                length = args['large-payload-chars'] if key < args['large-keys'] else 64
                lexical = f'urn:phase-memo:value:{key:08d}:'.ljust(length, 'x')
                h = 0
                for byte in lexical.encode('ascii'):
                    h = (31 * h + byte) & M32
                hashes[key] = h if h < (1 << 31) else h - (1 << 32)
                lengths[key] = length
            recipe.update(struct.pack('>iiii', row, column, key, lengths[key]))
            characters += lengths[key]
            row_hash = ((row_hash ^ (hashes[key] & M64)) * 0x100000001B3) & M64
        checksum = (checksum + (row + 1) * row_hash) & M64
    query = 'SELECT' + ''.join(f' ?v{c}' for c in range(width)) + ' WHERE {\n'
    query += ''.join(f'  ?row <urn:phase-memo:p{c}> ?v{c} .\n' for c in range(width))
    query += '} ORDER BY ?row\n'
    return {'rows': total // width, 'checksum': str(checksum if checksum < (1 << 63) else checksum - (1 << 64)),
            'opportunities': total, 'querySha256': hashlib.sha256(query.encode()).hexdigest(),
            'insertionRecipeSha256': recipe.hexdigest(), 'projectedLexicalChars': characters}


def verify_inputs(items):
    files = byte_count = 0
    for item in items:
        path = Path(item['path'])
        if item['kind'] == 'file':
            targets = [(path, item)]
        else:
            need(item['kind'] == 'tree', 'Unknown input kind')
            names = {p.relative_to(path).as_posix() for p in path.rglob('*') if p.is_file()
                     and (not item['sourceOnly'] or p.suffix in {'.java', '.py', '.xml', '.properties'})}
            need(names == {f['name'] for f in item['files']}, 'Frozen input membership changed: ' + str(path))
            targets = [(path / f['name'], f) for f in item['files']]
        for target, expected in targets:
            need(target.stat().st_size == expected['bytes'] and sha(target) == expected['sha256'],
                 'Frozen input changed: ' + str(target))
            files += 1
            byte_count += expected['bytes']
    return {'manifestEntries': len(items), 'fileChecksIncludingRepeatedInputs': files,
            'bytesHashedIncludingRepeatedInputs': byte_count}


def gc_observations(path):
    lines = path.read_text().splitlines()
    need(any('Using G1' in line for line in lines), 'Missing G1 identity')
    need(not any(word in line for line in lines for word in
                 ('System.gc()', 'Diagnostic Command', 'Heap Inspection Initiated GC')), 'Explicit GC in timing JVM')
    ids, pauses, concurrent, kinds = set(), [], [], Counter()
    for line in lines:
        match = re.search(r'GC\((\d+)\) (.*)', line)
        if match is None:
            continue
        ids.add(int(match.group(1)))
        body = match.group(2)
        duration = re.search(r' (\d+(?:\.\d+)?)ms$', body)
        if duration and body.startswith('Pause '):
            pauses.append(float(duration.group(1)))
            kinds[' '.join(body.split()[:2])] += 1
        elif duration and body.startswith('Concurrent '):
            concurrent.append(float(duration.group(1)))
    return {'gcIdsObserved': len(ids), 'pauseCount': len(pauses), 'pauseMs': sum(pauses),
            'pauseMaxMs': max(pauses, default=0), 'pauseKinds': dict(kinds),
            'completedConcurrentCycles': len(concurrent), 'concurrentCycleMs': sum(concurrent)}


def check_owner(owner, sample, index, arm):
    need(all(integer(v) for v in owner.values()), 'Invalid owner primitive')
    need(owner['ownerOrdinal'] == owner['compileOrdinalAtOpen'] == owner['compileOrdinalAtClose'] == index + 1,
         'Native owner/query mismatch')
    need(0 <= owner['lazyValueCallsAtClose'] - owner['lazyValueCallsAtOpen'] <= sample['counters']['lazyValueCalls'],
         'Invalid source observation interval')
    need(all(owner[k] == 0 for k in ('invalidations', 'unsupportedValues', 'rehashDiscards',
                                    'initialAdmissionRefusals', 'growthAdmissionRefusals', 'arrayBytesAfterClose')),
         'Unexpected identity, admission refusal, rehash, or cleanup event')
    probes, hits, growth, capacity = (owner[k] for k in ('probes', 'hits', 'resizes', 'peakCapacity'))
    need(owner['weakRetention'] == 1 and owner['ownerReferenceAllocations'] <= owner['weakEntryAllocations'],
         'Weak retention observation mismatch')
    need(hits + owner['collisions'] + owner['collectedMisses'] <= probes, 'Impossible probe categories')
    need(0 <= growth <= 4 and capacity == 4096 * 2 ** growth, 'Invalid capacity history')
    if growth:
        need(probes >= 8192 * (growth + 1) and hits >= 2048 * (growth + 1)
             and owner['collisions'] >= 1024 * (growth + 1), 'Growth predates necessary cumulative evidence')
    sizes = [capacity] + ([capacity // 2] if growth else [])
    array_peak = sum(80 + 36 * n for n in sizes)
    reservation_peak = sum(240 + 148 * n for n in sizes)
    need(owner['peakArrayBytes'] == array_peak and owner['peakReservationBytes'] == reservation_peak
         and reservation_peak <= sample['ledgerPeakBytes'], 'Reservation or resize-overlap accounting mismatch')
    cutoff = owner['lowHitDisable']
    need(cutoff in (0, 1) and owner['disabledAtClose'] == cutoff, 'Unexpected disable path')
    if cutoff:
        need(arm == 'initial' and probes == 8192 and hits < 2048 and growth == 0
             and owner['capacityAtClose'] == owner['retainedEntriesAtClose'] == 0, 'Illegal initial cutoff')
    else:
        need(probes == sample['projectedOpportunities'] and owner['capacityAtClose'] == capacity,
             'Active memo did not observe every qualified opportunity')
        need(arm != 'initial' or probes < 8192 or hits >= 2048, 'Initial memo could not survive first window')
    need(owner['retainedEntriesAtClose'] <= owner['capacityAtClose'], 'Invalid occupied slot count')


def metrics(sample):
    values = {k: sample[k] for k in METRICS}
    values['lazyValueCalls'] = sample['counters']['lazyValueCalls']
    boundary = sample['sourceLazyCallsAtPrefixBoundary']
    values['sourceLazyCallsAfterPrefixBoundary'] = None if boundary is None else values['lazyValueCalls'] - boundary
    return values


def normalize_metadata(metadata):
    value = {k: v for k, v in metadata.items() if k not in ('arm', 'store', 'admission')}
    differences = ('rdf4j.lmdb.nativeValueMemo.enabled', 'rdf4j.lmdb.nativeValueMemo.admission')
    value['systemProperties'] = {k: v for k, v in value['systemProperties'].items() if k not in differences}
    value['jvmArguments'] = ['<per-process-gc-log>' if arg.startswith('-Xlog:gc:file=') else arg
        for arg in value['jvmArguments'] if not any(arg.startswith('-D' + key + '=') for key in differences)]
    return value


def audit_slot(protocol, slot, oracle):
    cohort, folder = Path(protocol['cohort']), Path(slot['directory'])
    claim_file = cohort / 'claims' / f"{slot['ordinal']:04d}.json"
    claim, terminal = read(claim_file), read(folder / 'completion.json')
    launch, process = read(folder / 'launch.json'), read(folder / 'process.json')
    before, after = read(folder / 'inputs-before.json'), read(folder / 'inputs-after.json')
    seal = sha(cohort / 'protocol.json')
    need(claim['ordinal'] == launch['ordinal'] == terminal['ordinal'] == slot['ordinal'], 'Slot identity mismatch')
    need(claim['protocolSha256'] == terminal['protocolSha256'] == seal
         and terminal['claimSha256'] == sha(claim_file), 'Claim or protocol seal mismatch')
    need(set(terminal['rawHashes']) == set(RAW)
         and all(sha(folder / name) == terminal['rawHashes'][name] for name in RAW), 'Raw completion seal mismatch')
    need(claim['command'] == launch['argv'] == slot['command']
         and claim['cwd'] == launch['cwd'] == protocol['cwd'], 'Actual command mismatch')
    need(before['verified'] is after['verified'] is True
         and before['inputIdentity'] == after['inputIdentity'] == protocol['inputIdentity'], 'Input receipt mismatch')
    need(before['checkedEpochNs'] <= claim['claimedEpochNs'] <= launch['startedEpochNs'] == process['startedEpochNs']
         <= process['finishedEpochNs'] <= after['checkedEpochNs'] <= terminal['completedEpochNs'], 'Invalid chronology')
    need(process['exitCode'] == 0 and process['failure'] is None, 'Process did not complete normally')
    need(not (folder / 'projected-trace.jsonl').exists(), 'Diagnostic trace in timing cohort')
    records = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines() if line.strip()]
    need(len(records) == 15 and records[0]['type'] == 'metadata' and records[-1]['type'] == 'completion',
         'Expected metadata, all 13 queries, then completion')
    metadata, samples, completion = records[0], records[1:14], records[-1]
    args, arm = protocol['fixtures'][slot['fixture']]['arguments'], slot['arm']
    need(metadata['source'] == protocol['sourceIdentity'] and metadata['arm'] == arm
         and metadata['store'] == str(folder / 'store') and metadata['javaVersion'] == protocol['javaVersion'],
         'Unmatched source, arm, store, or JDK identity')
    need(metadata['jvmArguments'] == slot['command'][1:slot['command'].index('-cp')]
         and metadata['systemProperties'] == {'rdf4j.lmdb.hotCounters': 'true',
         'rdf4j.lmdb.queryMemory.perQueryMaxBytes': '536870912', **slot['properties']}, 'Actual JVM flags differ')
    for key in ('querySha256', 'insertionRecipeSha256', 'projectedLexicalChars'):
        need(metadata[key] == oracle[key], 'Independent fixture identity mismatch: ' + key)
    need(metadata['sourceCacheSettingsChanged'] is False and metadata['retainedOrderedRows'] is True
         and metadata['trace'] is metadata['exactOracle'] is metadata['timingAccepted'] is False
         and metadata['timingEligible'] is True and metadata['memoStatisticsCapacity'] == 13,
         'Diagnostic or source-cache setup changed')
    need(metadata['perQueryLedgerLimitBytes'] == 536870912 and metadata['globalLedgerLimitBytes'] == 1073741824
         and metadata['maxHeapBytes'] == 1073741824, 'Memory limits changed')
    routes, owners, residuals = [], [], []
    for index, sample in enumerate(samples):
        need(sample['type'] == 'sample' and sample['iteration'] == index - 8
             and sample['stage'] == ('warmup' if index < 8 else 'measurement'), 'Query order or stage changed')
        need(sample['arm'] == arm and sample['rows'] == oracle['rows'] and sample['checksum'] == oracle['checksum']
             and sample['projectedOpportunities'] == oracle['opportunities'], 'Result oracle failed')
        need(sample['orderedExactLexicalOracleValid'] is None and sample['exactOracle'] is False
             and sample['timingAccepted'] is False and sample['timingEligible'] is True
             and sample['oracleMode'] == 'checksum', 'Timing consumer includes exact diagnostic work')
        need(all(sample[k] is True for k in ('valid', 'complete', 'rowCountValid', 'checksumValid', 'ledgerReleased',
             'memoLifecycleValid', 'auto', 'autoRequested', 'nativeRouteObserved')), 'Result/lifetime flag failed')
        need(sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0
             and sample['queryLedgerPeakBytes'] is None and integer(sample['ledgerPeakBytes']), 'Ledger scope/endpoints failed')
        need(all(integer(sample[k]) for k in METRICS), 'Missing or invalid full-consumption metric')
        need(sum(sample[k] for k in ('connectionNs', 'prepareNs', 'evaluateNs', 'consumeNs', 'closeNs',
             'retainedReadNs')) == sample['totalNs'] > 0, 'Timing intervals do not sum to total')
        need(sample['prefixConsumeNs'] + sample['tailConsumeNs'] == sample['consumeNs']
             and sample['firstRowAfterEvaluateNs'] <= sample['consumeNs'], 'Phase intervals do not reconcile')
        counters = sample['counters']
        need(all(integer(v) for v in counters.values()) and all(counters[k] == 0 for k in IR_ZERO)
             and counters['semanticNativeCompiles'] == counters['chunkEngaged'] == counters['factorizedEngagement'] == 1,
             'Actual native route changed')
        need(sample['successfulSelections'] == ROUTE and sample['omittedSelections'] == 0
             and sample['nativeProjectedRows'] == oracle['rows'], 'Normal ordered-factorized AUTO route changed')
        adjacency = sample['adjacency']
        need(adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE', 'Adjacency inactive')
        revisions = [adjacency[k] for k in ('appliedRevisionBefore', 'currentRevisionBefore',
                                          'appliedRevisionAfter', 'currentRevisionAfter')]
        need(len(set(revisions + [metadata['adjacencySetup']['currentDataRevision']])) == 1, 'Stale adjacency revision')
        routes.append({'selections': sample['successfulSelections'], 'adjacency': adjacency,
                       'counters': {k: v for k, v in counters.items() if k != 'lazyValueCalls'}})
        count = int(arm != 'ordinary')
        need(sample['memoOpenedDelta'] == sample['memoClosedDelta'] == len(sample['memoOwners']) == count
             and sample['memoOverflowCount'] == 0, 'Owner lifecycle mismatch')
        for owner in sample['memoOwners']:
            check_owner(owner, sample, index, arm)
            need(not owners or owner['lazyValueCallsAtOpen'] >= owners[-1]['lazyValueCallsAtClose'],
                 'Source owner intervals overlap')
            owners.append(owner)
        hits = sum(owner['hits'] for owner in sample['memoOwners'])
        need(sample['projectedMaterializedValues'] + hits == oracle['opportunities'], 'Projection exposure mismatch')
        need(sample['sourceLazyCallsAtPrefixBoundary'] <= counters['lazyValueCalls']
             and sample['projectedMaterializedValuesAtPrefixBoundary'] <= sample['projectedMaterializedValues'],
             'Boundary counters exceed query observations')
        residuals.append(counters['lazyValueCalls'] - sample['projectedMaterializedValues'])
    expected_owners = 13 * int(arm != 'ordinary')
    need(completion['harnessReturned'] is True and completion['queries'] == 13 and completion['warmups'] == 8
         and completion['measurements'] == 5 and completion['semanticNativeCompilesTotal'] == 13
         and completion['hostedGenericTotal'] == completion['unhostedHardDeclinesTotal'] == completion['ledgerAfterBytes'] == 0
         and completion['memoOpenedTotal'] == completion['memoClosedTotal'] == completion['memoStatisticsSize'] == expected_owners
         and completion['memoOverflowCount'] == 0, 'Final query/root/cleanup audit failed')
    values = [metrics(sample) for sample in samples[8:]]
    medians = {key: reduce_values(v[key] for v in values) for key in values[0]}
    means = {key: reduce_values((v[key] for v in values), mean=True) for key in values[0]}
    owner_medians = {k: median(o[k] for o in owners[8:]) for k in owners[0]} if owners else {}
    if owners:
        owner_medians['hitRate'] = median(o['hits'] / o['probes'] for o in owners[8:])
    return {'ordinal': slot['ordinal'], 'round': slot['round'], 'fixture': slot['fixture'], 'arm': arm,
            'medians': medians, 'means': means, 'ownerMedians': owner_medians,
            'measuredQueryValues': values, 'measuredOwners': owners[8:],
            'sourceMinusProjectedMaterializations': residuals, 'gc': gc_observations(folder / 'gc.log'),
            'rawCompletionSha256': sha(folder / 'completion.json'), 'process': process,
            'normalizedMetadata': normalize_metadata(metadata), 'routes': routes}


def compare_subset(expected, actual, path='root'):
    if isinstance(expected, dict):
        need(isinstance(actual, dict), path + ': expected object')
        for key, value in expected.items():
            need(key in actual, path + ': missing ' + key)
            compare_subset(value, actual[key], path + '.' + key)
    elif isinstance(expected, list):
        need(isinstance(actual, list) and len(expected) == len(actual), path + ': list length')
        for i, (left, right) in enumerate(zip(expected, actual)):
            compare_subset(left, right, path + '[' + str(i) + ']')
    elif isinstance(expected, (int, float)) and type(expected) is not bool:
        need(type(actual) in (int, float) and math.isfinite(actual)
             and math.isclose(expected, actual, rel_tol=1e-12, abs_tol=1e-12), path + ': numerical mismatch')
    else:
        need(type(expected) is type(actual) and expected == actual, path + ': value mismatch')


def audit(cohort, primary=None):
    protocol = read(cohort / 'protocol.json')
    need(sha(cohort / 'protocol.json') == (cohort / 'protocol.sha256').read_text().strip(), 'Protocol seal failed')
    need(protocol['cohort'] == str(cohort) and protocol['format'] == 'rdf4j-phase-admission-comparison-v1'
         and protocol['arms'] == list(ARMS) and protocol['warmups'] == 8 and protocol['measurements'] == 5
         and protocol['rounds'] == 6, 'Unrecognized fixed protocol')
    need(not (cohort / 'failure.json').exists(), 'Cohort has a preserved failure; no accepted estimates')
    need(protocol['jvmArguments'] == FIXED_FLAGS and object_sha(protocol['inputs']) == protocol['inputIdentity'],
         'Fixed arguments or input identity changed')
    fixtures = protocol['fixtureOrder']
    need(len(fixtures) == 3 and set(fixtures) == set(protocol['fixtures']), 'This audit expects the three-fixture study')
    expected = [(r, fp, fixtures[fi], ap, arm) for r, arms in enumerate(itertools.permutations(ARMS))
                for fp, fi in enumerate(ORDERS[r]) for ap, arm in enumerate(arms)]
    schedule = protocol['schedule']
    need([(s['round'], s['fixturePosition'], s['fixture'], s['position'], s['arm']) for s in schedule] == expected
         and [s['ordinal'] for s in schedule] == list(range(54)), 'Finite balanced schedule changed')
    need({p.name for p in (cohort / 'claims').iterdir()} == {f'{i:04d}.json' for i in range(54)}
         and {p.name for p in cohort.glob('round-*')} == {Path(s['directory']).name for s in schedule},
         'Missing, extra, or unclaimed process')
    input_check = verify_inputs(protocol['inputs'])
    oracles = {name: fixture_oracle(protocol['fixtures'][name]['arguments']) for name in fixtures}
    for name, oracle in oracles.items():
        compare_subset({'rows': oracle['rows'], 'fullRows': oracle['rows'], 'checksum': oracle['checksum'],
                        'fullChecksum': oracle['checksum']}, protocol['fixtures'][name]['oracle'], name + '.oracle')
    for slot in schedule:
        folder, command = Path(slot['directory']), slot['command']
        need(folder.parent == cohort and command[0] == protocol['java'] and command.count('-cp') == 1,
             'Run path, launcher, or classpath changed')
        properties = {'rdf4j.lmdb.resultCoordinateTransport': 'off',
                      'rdf4j.lmdb.nativeValueMemo.enabled': str(slot['arm'] != 'ordinary').lower(),
                      'rdf4j.lmdb.nativeValueMemo.retention': 'weak',
                      'rdf4j.lmdb.nativeValueMemo.admission': 'always' if slot['arm'] == 'always' else 'initial'}
        need(slot['properties'] == properties, 'Not the cutoff-only ablation')
        cp_at = command.index('-cp')
        flags = FIXED_FLAGS + ['-Xlog:gc:file=' + str(folder / 'gc.log') + ':uptime,level,tags']
        flags += ['-D' + key + '=' + value for key, value in properties.items()]
        need(Counter(command[1:cp_at]) == Counter(flags) and command[cp_at + 1] == ':'.join(protocol['classpath'])
             and command[cp_at + 2] == 'org.eclipse.rdf4j.sail.lmdb.evaluation.PhaseMemoQueryHarness', 'Runtime flags differ')
        raw_args = command[cp_at + 3:]
        need(all(arg.startswith('--') and '=' in arg for arg in raw_args), 'Malformed harness argument')
        actual = dict(arg[2:].split('=', 1) for arg in raw_args)
        wanted = {key: str(value) for key, value in protocol['fixtures'][slot['fixture']]['arguments'].items()}
        wanted.update(arm=slot['arm'], source=protocol['sourceIdentity'], warmup='8', iterations='5', trace='false',
                      **{'exact-oracle': 'false', 'output': str(folder / 'samples.jsonl'), 'store': str(folder / 'store')})
        need(actual == wanted and len(actual) == len(raw_args), 'Changed, extra, or duplicate harness argument')
    runs = [audit_slot(protocol, slot, oracles[slot['fixture']]) for slot in schedule]
    last_end, metadata, routes = 0, {}, {}
    for run in runs:
        need(run['process']['startedEpochNs'] >= last_end, 'Scheduled JVM intervals overlap')
        last_end = run['process']['finishedEpochNs']
        name = run['fixture']
        metadata.setdefault(name, run['normalizedMetadata'])
        routes.setdefault(name, run['routes'])
        need(metadata[name] == run['normalizedMetadata'] and routes[name] == run['routes'],
             'Cross-arm/round metadata, AUTO route, or adjacency mismatch')
    index = {(r['fixture'], r['round'], r['arm']): r for r in runs}
    comparisons, absolutes = [], []
    for name in fixtures:
        for arm in ARMS:
            chosen = [index[name, r, arm] for r in range(6)]
            owners = [owner for run in chosen for owner in run['measuredOwners']]
            values = [sample for run in chosen for sample in run['measuredQueryValues']]
            absolutes.append({'fixture': name, 'arm': arm,
                'medianOfJvmMedians': {k: median(r['medians'][k] for r in chosen) for k in chosen[0]['medians']},
                'secondaryMedianOfJvmMeans': {k: median(r['means'][k] for r in chosen) for k in chosen[0]['means']},
                'ownerMedianOfJvmMedians': {k: median(r['ownerMedians'][k] for r in chosen) for k in chosen[0]['ownerMedians']},
                'measuredOwnerRanges': {k: [min(o[k] for o in owners), max(o[k] for o in owners)] for k in owners[0]} if owners else {},
                'measuredOwnerEventTotals': {k: sum(o[k] for o in owners) for k in EVENTS} if owners else {},
                'measuredSourceCallRange': [min(v['lazyValueCalls'] for v in values), max(v['lazyValueCalls'] for v in values)],
                'wholeJvmGcMedians': {k: median(r['gc'][k] for r in chosen) for k in ('gcIdsObserved', 'pauseCount',
                    'pauseMs', 'pauseMaxMs', 'completedConcurrentCycles', 'concurrentCycleMs')}})
        for numerator, denominator in PAIRS:
            comparison = {'fixture': name, 'candidate': numerator, 'comparator': denominator}
            for label, field in (('primary', 'medians'), ('secondaryMeanSensitivity', 'means')):
                estimates = {}
                for key in index[name, 0, numerator][field]:
                    pairs = [(index[name, r, numerator][field][key], index[name, r, denominator][field][key]) for r in range(6)]
                    estimates[key] = ratios([a / b if a is not None and b not in (None, 0) else None for a, b in pairs])
                comparison[label] = estimates
            comparison['latencyDirectionDisagrees'] = (comparison['primary']['totalNs']['medianRatio'] < 1) != (
                comparison['secondaryMeanSensitivity']['totalNs']['medianRatio'] < 1)
            comparisons.append(comparison)
    result = {'complete': True, 'protocolSha256': sha(cohort / 'protocol.json'), 'independentInputRehash': input_check,
        'independentFixtureOracles': oracles, 'counts': {'jvms': 54, 'queries': 702, 'warmups': 432, 'measurements': 270},
        'replication': 'Six fresh processes per fixture/arm. Five measurements are nested within each process. '
                       'The nine comparisons share controls and are descriptive; no inferential claim.',
        'memoryScope': 'Global process-authority accounting during serial query windows; no separate query-ledger '
                       'peak or total retained-heap estimate. Metadata reservations are checked including resize overlap.',
        'counterScope': 'Lazy source calls are not physical decodes. Cleared occupied-slot observations precede key '
                        'comparison; occupied wrappers at close are not a live-Value census. No cross-process ID equality assumed.',
        'gcScope': 'Natural G1 events over each whole JVM, including setup and warmups. Concurrent durations overlap. '
                   'Ordered rows retain Values, so these results do not establish useful-key GC rematerialization.',
        'exclusions': 'No process, query, latency, allocation, hit rate, collision outcome, or GC event was dropped.',
        'absolutes': absolutes, 'comparisons': comparisons,
        'jvmResults': [{k: v for k, v in run.items() if k not in ('normalizedMetadata', 'routes', 'process', 'measuredOwners')}
                       for run in runs]}
    if primary is not None:
        original = read(primary)
        compare_subset({k: result[k] for k in ('complete', 'protocolSha256', 'counts', 'absolutes', 'comparisons')}, original)
        compare_subset([{k: r[k] for k in ('ordinal', 'round', 'fixture', 'arm', 'medians', 'means', 'ownerMedians', 'gc')}
                        for r in result['jvmResults']], original['jvmResults'], 'jvmResults')
        result['primaryNumericalAgreement'] = {'verified': True, 'path': str(primary), 'sha256': sha(primary),
                                              'relativeAndAbsoluteTolerance': 1e-12}
    return result


def self_check():
    need(median([1, 1, 1, 1, 96]) == 1 and reduce_values([1, 1, 1, 1, 96], mean=True) == 20,
         'Median/mean sensitivity arithmetic failed')
    a, b = [1, 2, 4, 8, 16, 32], [1, 1, 1, 16, 16, 16]
    need(median(x / y for x, y in zip(a, b)) == 1.5 and median(a) / median(b) != 1.5,
         'Paired estimator accidentally became a ratio of marginal summaries')
    need(ratios([None, 0, 1, 2, 3, 4])['definedPairs'] == 5, 'Undefined-ratio accounting failed')
    permutations = list(itertools.permutations(range(3)))
    def repetitions(orders):
        cells = Counter((f, a, fp, ap) for r, fs in enumerate(orders)
                        for fp, f in enumerate(fs) for ap, a in enumerate(permutations[r]))
        return sum(n - 1 for n in cells.values())
    need(repetitions(ORDERS) == min(repetitions(x) for x in itertools.permutations(permutations)) == 5,
         'Prospective fixture-order claim failed')
    checked = {}
    for name, pattern, prefix, expected in (
            ('early', 'cold-hot', 4096, '-392792955594352548'),
            ('late', 'cold-hot', 32768, '-1128082570782671460'),
            ('hot-unique', 'hot-unique', 8192, '-7925248249943514788')):
        args = {'pattern': pattern, 'prefix-probes': prefix, 'tail-probes': 131072 - prefix,
                'working-set': 64, 'bootstrap-keys': 64, 'width': 4, 'large-keys': 0,
                'large-payload-chars': 1048577, 'consumption': 'full'}
        checked[name] = fixture_oracle(args)
        need(checked[name]['checksum'] == expected, 'Independent ASCII oracle differs: ' + name)
    return {'selfCheckPassed': True, 'cohortRead': False, 'jvmsLaunched': 0,
            'pairedEstimatorTripwire': 1.5, 'minimumRepeatedJointOrderCells': 5, 'fixtureOracles': checked}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument('--cohort', type=Path)
    mode.add_argument('--self-check', action='store_true')
    parser.add_argument('--primary', type=Path)
    parser.add_argument('--output', type=Path)
    args = parser.parse_args()
    need(not args.self_check or args.primary is None, '--primary requires a completed cohort')
    if args.output is not None:
        need(not args.output.exists(), 'Use a new output path; preserve prior audit receipts')
    result = self_check() if args.self_check else audit(args.cohort.resolve(strict=True),
             args.primary.resolve(strict=True) if args.primary else None)
    result['auditSourceSha256'] = sha(__file__)
    encoded = json.dumps(result, indent=2, sort_keys=True, allow_nan=False) + '\n'
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        with args.output.open('x') as stream:
            stream.write(encoded)
        print(json.dumps({'complete': result.get('complete'), 'selfCheckPassed': result.get('selfCheckPassed'),
                          'output': str(args.output), 'auditSourceSha256': result['auditSourceSha256']}))
    else:
        print(encoded, end='')


if __name__ == '__main__':
    main()
